function validate([word1, word2]) {
  if (word1.length < 1 || word2.length < 1) return 'Each word needs at least one letter.';
  if (word1.length > 100000 || word2.length > 100000) return 'Each word has at most 10^5 letters.';
  if (!/^[a-z]+$/.test(word1) || !/^[a-z]+$/.test(word2)) return 'Use only lowercase English letters.';
  return null;
}

