function closeStrings(word1, word2) {
  // Swaps reach every ordering, so a string is identified by its sorted form; search the relabel moves from there.
  const sorted = s => s.split('').sort().join('');
  const start = sorted(word1), goal = sorted(word2);
  const seen = new Set([start]);
  const queue = [start];
  while (queue.length) {
    const current = queue.shift();
    if (current === goal) return true;
    const present = [...new Set(current.split(''))];
    for (let i = 0; i < present.length; i++)
      for (let j = i + 1; j < present.length; j++) {
        const a = present[i], b = present[j];
        const next = sorted(current.split('').map(c => c === a ? b : c === b ? a : c).join(''));
        if (!seen.has(next)) { seen.add(next); queue.push(next); }
      }
  }
  return false;
}

