function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = pick(i + 1); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  const all = 'abcdefghijklmnopqrstuvwxyz';
  const k = size === 'large' ? 1 + pick(26) : 1 + pick(4);
  const offset = pick(27 - k);
  const alphabet = all.slice(offset, offset + k).split('');
  const n = size === 'large' ? 5000 + pick(5001) : 1 + pick(7);
  const word1 = Array.from({ length: n }, () => alphabet[pick(k)]).join('');
  const mode = rand();
  if (mode < 0.55) {
    // A close partner: relabel the letters by a random permutation, then shuffle the positions.
    const used = [...new Set(word1.split(''))];
    const image = shuffle(used.slice());
    const chars = shuffle(word1.split('').map(c => image[used.indexOf(c)]));
    // Sometimes change one character, which usually breaks closeness.
    if (mode < 0.2) chars[pick(chars.length)] = all[offset + pick(Math.min(k + 1, 26 - offset))];
    return [word1, chars.join('')];
  }
  const m = size === 'large' ? n : rand() < 0.7 ? n : 1 + pick(7);
  const other = all.slice(offset, offset + Math.min(k + (rand() < 0.3 ? 1 : 0), 26 - offset));
  return [word1, Array.from({ length: m }, () => other[pick(other.length)]).join('')];
}
